	('a842eb8a-675d-40da-b3b4-d87383223134', 'Youth Digital Futures Hackday', '{"purpose": "Give young participants hands-on experience in problem solving, teamwork, and responsible technology design.", "decision": {"reason": null, "status": "Approved", "decidedAt": "2026-09-18T14:44:42.070656+00:00", "coordinatorId": "e7334aa9-eb3a-4c45-84b5-280501b6c109"}, "description": "A one-day collaborative challenge where students prototype digital ideas for education and community life.", "_connectsphere": "event-submission-v1", "decisionHistory": [{"reason": null, "status": "Approved", "decidedAt": "2026-09-18T14:44:42.070656+00:00", "coordinatorId": "e7334aa9-eb3a-4c45-84b5-280501b6c109"}]}', 160, '2027-01-23 01:00:00+00', '2027-01-23 10:00:00+00', 'Approved', NULL, 'e7334aa9-eb3a-4c45-84b5-280501b6c109', '2026-09-16 12:57:21.3557+00', 'Large room with team tables, mentor corner, presentation area, and secure equipment storage.', 'Step-free access, adjustable-height tables, quiet working area, and accessible restrooms.', 'Reliable Wi-Fi, power strips, 80 laptops or charging points, projector, microphones, and timers.', 'Participant registration, guardian consent, emergency contacts, team allocation, and meal preferences.', 'Give young participants hands-on experience in problem solving, teamwork, and responsible technology design.', false, NULL, NULL, NULL, NULL),
	('3c06f811-53fb-4779-a4c5-507e0bb681ee', 'Community Workshop', '{"purpose": "Community engagement", "decision": {"reason": null, "status": "Approved", "decidedAt": "2026-10-02T04:59:18.626127+00:00", "coordinatorId": "e7334aa9-eb3a-4c45-84b5-280501b6c109"}, "description": "A hands-on workshop for local community members.", "_connectsphere": "event-submission-v1", "decisionHistory": [{"reason": null, "status": "Approved", "decidedAt": "2026-10-02T04:59:18.626127+00:00", "coordinatorId": "e7334aa9-eb3a-4c45-84b5-280501b6c109"}]}', 60, '2026-10-05 01:00:00+00', '2026-10-05 09:00:00+00', 'Approved', '3d89d4d2-3502-4bd9-ade8-c9887f2bee45', 'e7334aa9-eb3a-4c45-84b5-280501b6c109', '2026-09-15 10:00:00+00', 'Innovation Lab', 'Wheelchair accessible entrance required', 'Projector, whiteboard', 'Online registration required', 'Community engagement', false, NULL, NULL, NULL, NULL),
