	('ef0dd422-b170-4025-95ef-449c3fa151a2', 'Asia-Pacific Product Leadership Summit', '{"purpose": "Exchange product management practices and build partnerships across the Asia-Pacific technology community.", "approval": {"approvedAt": "2026-09-16T15:29:46.508682+00:00", "coordinatorId": "e7334aa9-eb3a-4c45-84b5-280501b6c109"}, "description": "A two-day summit bringing product leaders together to share practical approaches to discovery, delivery, and responsible growth.", "_connectsphere": "event-submission-v1"}', 220, '2026-10-15 01:00:00+00', '2026-10-15 09:30:00+00', 'Approved', NULL, 'e7334aa9-eb3a-4c45-84b5-280501b6c109', '2026-09-16 12:57:19.201584+00', 'Theatre seating for 220, main stage, registration foyer, and two breakout rooms.', 'Step-free access, accessible washrooms, reserved wheelchair spaces, and captioning.', 'Projector, confidence monitor, stage microphones, four wireless microphones, and recording support.', 'Online registration, QR check-in, dietary preference collection, and attendance badges.', 'Exchange product management practices and build partnerships across the Asia-Pacific technology community.', false, NULL, NULL, NULL, NULL),
